sys_script_client.script:
function onSubmit() {

    // --------------------------------------------------
    // 1. Mandatory field validation
    // --------------------------------------------------

    if (!g_form.getValue('patient')) {
        g_form.addErrorMessage('Patient is required.');
        return false;
    }

    if (!g_form.getValue('insight_type')) {
        g_form.addErrorMessage('Insight Type is required.');
        return false;
    }

    if (!g_form.getValue('severity')) {
        g_form.addErrorMessage('Severity is required.');
        return false;
    }

    if (!g_form.getValue('insight_title')) {
        g_form.addErrorMessage('Insight Title is required.');
        return false;
    }

    if (!g_form.getValue('insight')) {
        g_form.addErrorMessage('Insight is required.');
        return false;
    }

    if (!g_form.getValue('generated_date')) {
        g_form.addErrorMessage('Generated Date is required.');
        return false;
    }


    // --------------------------------------------------
    // 2. Reviewed workflow validation
    // --------------------------------------------------

    var insightStatus = g_form.getValue('insight_status');

    if (insightStatus == 'Reviewed' ||
        insightStatus == 'Accepted' ||
        insightStatus == 'Rejected' ||
        insightStatus == 'Resolved') {

        if (!g_form.getValue('reviewed_by')) {
            g_form.addErrorMessage(
                'Reviewed By is required when Insight Status is Reviewed, Accepted, Rejected, or Resolved.'
            );

            return false;
        }

        if (!g_form.getValue('review_notes')) {
            g_form.addErrorMessage(
                'Review Notes are required when Insight Status is Reviewed, Accepted, Rejected, or Resolved.'
            );

            return false;
        }
    }


    // --------------------------------------------------
    // 3. Confidence Score validation
    // --------------------------------------------------

    var confidenceScore = g_form.getValue('confidence_score');

    if (confidenceScore) {

        if (isNaN(parseFloat(confidenceScore))) {

            g_form.addErrorMessage(
                'Confidence Score must contain a valid numeric value.'
            );

            return false;
        }
    }


    // --------------------------------------------------
    // All validations passed
    // --------------------------------------------------

    return true;
}
